16		"charm.land/lipgloss/v2"
17	)
18	
19	// traceStep represents a single timed step within a trace span.
20	// Nested spans are represented as SubSteps. Loop iterations keep their numeric
21	// suffixes in the step name, e.g. "process_sessions.0".
22	type traceStep struct {
23		Name       string
24		DurationMs int64
25		Error      bool
26		SubSteps   []traceStep
27	}
28	
29	// traceEntry represents a parsed performance trace log entry.
30	type traceEntry struct {
31		Op         string
32		DurationMs int64
33		Error      bool
34		Time       time.Time
35		Steps      []traceStep
36	}
37	
38	// parseTraceEntry parses a JSON log line into a traceEntry.
39	// Returns nil if the line is not valid JSON or is not a trace entry (msg != "perf").
40	func parseTraceEntry(line string) *traceEntry {
41		// Cheap pre-filter: skip full JSON parse for lines that can't be perf entries.
42		// Most lines in the shared log file are non-perf, so this avoids the
43		// marshalling cost for the common reject path.
44		if !strings.Contains(line, `"msg":"perf"`) {
45			return nil
46		}
47	
48		var raw map[string]json.RawMessage
49		if err := json.Unmarshal([]byte(line), &raw); err != nil {
50			return nil
51		}
52	
53		// Verify msg == "perf" after full parse (the pre-filter could match substrings)
54		var msg string
55		if msgRaw, ok := raw["msg"]; !ok {
56			return nil
57		} else if err := json.Unmarshal(msgRaw, &msg); err != nil || msg != "perf" {
58			return nil
59		}
60	
61		entry := &traceEntry{}
62	
63		// Best-effort field extraction: missing or mistyped fields keep their
64		// zero values rather than discarding the entire entry.
65		if opRaw, ok := raw["op"]; ok {
66			_ = json.Unmarshal(opRaw, &entry.Op) //nolint:errcheck // best-effort
67		}
68		if dRaw, ok := raw["duration_ms"]; ok {
69			_ = json.Unmarshal(dRaw, &entry.DurationMs) //nolint:errcheck // best-effort
70		}
71		if errRaw, ok := raw["error"]; ok {
72			_ = json.Unmarshal(errRaw, &entry.Error) //nolint:errcheck // best-effort
73		}
74	
75		// Extract time
76		if tRaw, ok := raw["time"]; ok {
77			var ts string
78			if err := json.Unmarshal(tRaw, &ts); err == nil {
79				if parsed, err := time.Parse(time.RFC3339, ts); err == nil {
80					entry.Time = parsed
81				}
82			}
83		}
84	
85		// Extract steps by finding keys matching "steps.*_ms"
86		stepDurations := make(map[string]int64)
87		stepErrors := make(map[string]bool)
88	
89		for key, val := range raw {
90			if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
91				name := strings.TrimPrefix(key, "steps.")
92				name = strings.TrimSuffix(name, "_ms")
93	
94				var ms int64
95				if err := json.Unmarshal(val, &ms); err == nil {
96					stepDurations[name] = ms
97				}
98			} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
99				name := strings.TrimPrefix(key, "steps.")
100				name = strings.TrimSuffix(name, "_err")
101	
102				var errFlag bool
103				if err := json.Unmarshal(val, &errFlag); err == nil {
104					stepErrors[name] = errFlag
105				}
106			}
107		}
108	
109		entry.Steps = buildTraceSteps(stepDurations, stepErrors)
110	
111		return entry
112	}
113	
114	type traceStepNode struct {
115		step     traceStep
116		children []*traceStepNode
117	}
118	
119	func buildTraceSteps(stepDurations map[string]int64, stepErrors map[string]bool) []traceStep {
120		nodes := make(map[string]*traceStepNode, len(stepDurations))
121		for name, ms := range stepDurations {
122			nodes[name] = &traceStepNode{
123				step: traceStep{
124					Name:       name,
125					DurationMs: ms,
126					Error:      stepErrors[name],
127				},
128			}
129		}
130	
131		roots := make([]*traceStepNode, 0, len(nodes))
132		for name, node := range nodes {
133			parentName, ok := traceStepParent(name, stepDurations)
134			if !ok {
135				roots = append(roots, node)
136				continue
137			}
138			nodes[parentName].children = append(nodes[parentName].children, node)
139		}
140	
141		return traceStepNodesToSteps(roots, "")
142	}
143	
144	func traceStepParent(name string, allSteps map[string]int64) (string, bool) {
145		candidate := name
146		for {
147			idx := strings.LastIndex(candidate, ".")
148			if idx < 0 {
149				return "", false
150			}
151			candidate = candidate[:idx]
152			if _, ok := allSteps[candidate]; ok {
153				return candidate, true
154			}
155		}
156	}
157	
158	func traceStepNodesToSteps(nodes []*traceStepNode, parentName string) []traceStep {
159		sortTraceStepNodes(nodes, parentName)
160	
161		steps := make([]traceStep, 0, len(nodes))
162		for _, node := range nodes {
163			step := node.step
164			step.SubSteps = traceStepNodesToSteps(node.children, step.Name)
165			steps = append(steps, step)
166		}
167		return steps
168	}
169	
170	func sortTraceStepNodes(nodes []*traceStepNode, parentName string) {
171		slices.SortFunc(nodes, func(a, b *traceStepNode) int {
172			if parentName == "" {
173				return cmp.Compare(a.step.Name, b.step.Name)
174			}
175	
176			aIdx, aNumeric := traceStepChildIndex(parentName, a.step.Name)
177			bIdx, bNumeric := traceStepChildIndex(parentName, b.step.Name)
178			if aNumeric && bNumeric {
179				return cmp.Compare(aIdx, bIdx)
180			}
181			if aNumeric {
182				return -1
183			}
184			if bNumeric {
185				return 1
186			}
187			return cmp.Compare(a.step.Name, b.step.Name)
188		})
189	}
190	
191	func traceStepChildIndex(parentName, childName string) (int, bool) {
192		prefix := parentName + "."
193		if !strings.HasPrefix(childName, prefix) {
194			return 0, false
195		}
196		suffix := strings.TrimPrefix(childName, prefix)
197		idx, err := strconv.Atoi(suffix)
198		if err != nil || idx < 0 {
199			return 0, false
200		}
201		return idx, true
202	}
203	
204	// collectTraceEntries reads a JSONL log file and returns the last N trace entries,
205	// ordered newest first. If hookFilter is non-empty, only entries with a matching
206	// Op field are included.
207	func collectTraceEntries(logFile string, last int, hookFilter string) ([]traceEntry, error) {
208		f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
209		if err != nil {
210			if errors.Is(err, os.ErrNotExist) {
211				return nil, nil
212			}
213			return nil, fmt.Errorf("opening log file: %w", err)
214		}
215		defer f.Close()
216	
217		var entries []traceEntry
218	
219		scanner := bufio.NewScanner(f)
220		scanner.Buffer(make([]byte, 0, bufio.MaxScanTokenSize), 1024*1024) // allow up to 1MB lines in shared log file
221		for scanner.Scan() {
222			entry := parseTraceEntry(scanner.Text())
223			if entry == nil {
224				continue
225			}
226			if hookFilter != "" && entry.Op != hookFilter {
227				continue
228			}
229			entries = append(entries, *entry)
230		}
231	
232		if err := scanner.Err(); err != nil {
233			return nil, fmt.Errorf("reading log file: %w", err)
234		}
235	
236		// Take the last N entries
237		if len(entries) > last {
238			entries = entries[len(entries)-last:]
239		}
240	
241		// Reverse so newest entries are first
242		slices.Reverse(entries)
243	
244		return entries, nil
245	}
