247	// renderTraceEntries writes a formatted table of trace entries to w.
248	// If entries is empty, it prints a help message about enabling traces.
249	func renderTraceEntries(w io.Writer, entries []traceEntry) {
250		if len(entries) == 0 {
251			fmt.Fprintln(w, "No trace entries found.")
252			fmt.Fprintln(w, `Traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set`)
253			fmt.Fprintln(w, `in your shell profile, or set log_level to "DEBUG" in .entire/settings.json.`)
254			return
255		}
256	
257		for i, entry := range entries {
258			if i > 0 {
259				fmt.Fprintln(w)
260			}
261	
262			header := fmt.Sprintf("%s  %dms", entry.Op, entry.DurationMs)
263			if !entry.Time.IsZero() {
264				header += "  " + entry.Time.Format(time.RFC3339)
265			}
266			fmt.Fprintln(w, header)
267			fmt.Fprintln(w)
268	
269			if len(entry.Steps) == 0 {
270				continue
271			}
272	
273			rows := flattenTraceSteps(entry.Steps)
274			nameWidth := lipgloss.Width("STEP")
275			for _, r := range rows {
276				nameWidth = max(nameWidth, lipgloss.Width(r.label))
277			}
278	
279			renderTraceTableRow(w, nameWidth, "STEP", "DURATION", false)
280			for _, r := range rows {
281				renderTraceTableRow(w, nameWidth, r.label, fmt.Sprintf("%dms", r.durationMs), r.err)
282			}
283		}
284	}
285	
286	type traceRenderRow struct {
287		label      string
288		durationMs int64
289		err        bool
290	}
291	
292	func flattenTraceSteps(steps []traceStep) []traceRenderRow {
293		var rows []traceRenderRow
