package checkpoint

// TEMPORARY profiling harness - delete before commit.
// Splits the cost of one createRedactedBlobFromFile call on a large Codex-shaped
// transcript, to find whether redaction or blob writing owns the ~67.8s observed
// in write_temporary_checkpoint.

import (
	"bytes"
	"context"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"math/rand"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/testutil"
	"github.com/entireio/cli/redact"
	"github.com/go-git/go-git/v6/utils/binary"
)

// buildCodexTranscript produces roughly targetBytes of Codex-rollout-shaped
// JSONL: a mix of large tool outputs (the realistic bulk) and reasoning items
// carrying base64 encrypted_content (the entropy-layer pathological case).
func buildCodexTranscript(targetBytes int) []byte {
	rng := rand.New(rand.NewSource(42))
	var buf bytes.Buffer
	blob := make([]byte, 24*1024)
	for buf.Len() < targetBytes {
		switch rng.Intn(3) {
		case 0:
			rng.Read(blob)
			line, _ := json.Marshal(map[string]any{
				"type": "response_item",
				"payload": map[string]any{
					"type": "reasoning",
					"content": []map[string]any{{
						"type":              "reasoning_text",
						"encrypted_content": base64.StdEncoding.EncodeToString(blob),
					}},
				},
			})
			buf.Write(line)
		case 1:
			// Large tool output: realistic prose-ish payload, low entropy.
			text := bytes.Repeat([]byte("the quick brown fox jumps over the lazy dog 0123456789 "), 400)
			line, _ := json.Marshal(map[string]any{
				"type": "response_item",
				"payload": map[string]any{
					"type":   "function_call_output",
					"output": string(text),
				},
			})
			buf.Write(line)
		default:
			line, _ := json.Marshal(map[string]any{
				"type": "response_item",
				"payload": map[string]any{
					"type":    "message",
					"role":    "assistant",
					"content": []map[string]any{{"type": "output_text", "text": bytes.NewBuffer(nil).String() + "some assistant reply with a token sk-abc123 and an email a@b.com"}},
				},
			})
			buf.Write(line)
		}
		buf.WriteByte('\n')
	}
	return buf.Bytes()
}

func TestProfileRedactVsBlobWrite(t *testing.T) {
	sizes := []int{5 << 20, 20 << 20, 70 << 20}

	tmp := t.TempDir()
	testutil.InitRepo(t, tmp)
	testutil.WriteFile(t, tmp, "f.txt", "init")
	testutil.GitAdd(t, tmp, "f.txt")
	testutil.GitCommit(t, tmp, "init")
	repo, err := gitOpenForProfile(tmp)
	if err != nil {
		t.Fatalf("open repo: %v", err)
	}

	ctx := context.Background()
	fmt.Printf("\n%-10s %10s %10s %10s %10s\n", "SIZE", "isBinary", "redact", "blobwrite", "TOTAL")
	for _, sz := range sizes {
		content := buildCodexTranscript(sz)

		t0 := time.Now()
		_, _ = binary.IsBinary(bytes.NewReader(content))
		dBin := time.Since(t0)

		t1 := time.Now()
		red := RedactBlobBytes(ctx, content, "full.jsonl", false)
		dRed := time.Since(t1)

		t2 := time.Now()
		if _, err := CreateBlobFromContent(repo, red); err != nil {
			t.Fatalf("blob: %v", err)
		}
		dBlob := time.Since(t2)

		fmt.Printf("%-10s %10s %10s %10s %10s   (in=%dMB out=%dMB)\n",
			fmt.Sprintf("%dMB", sz>>20),
			dBin.Round(time.Millisecond), dRed.Round(time.Millisecond),
			dBlob.Round(time.Millisecond), (dBin + dRed + dBlob).Round(time.Millisecond),
			len(content)>>20, len(red)>>20)
	}
	_ = redact.Bytes
}

