package checkpoint

import (
	"bytes"
	"fmt"
	"runtime"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/entireio/cli/redact"
)

// parallelJSONL redacts JSONL by splitting on lines and processing shards
// concurrently. Lines are independent under the stateless regex redactor, so
// output must be byte-identical to the sequential path.
func parallelJSONL(content string, shards int) string {
	lines := strings.Split(content, "\n")
	if shards < 1 {
		shards = 1
	}
	per := (len(lines) + shards - 1) / shards
	out := make([]string, shards)
	var wg sync.WaitGroup
	for s := 0; s < shards; s++ {
		lo := s * per
		hi := min(lo+per, len(lines))
		if lo >= hi {
			continue
		}
		wg.Add(1)
		go func(idx, lo, hi int) {
			defer wg.Done()
			r, err := redact.JSONLContent(strings.Join(lines[lo:hi], "\n"))
			if err != nil {
				r = strings.Join(lines[lo:hi], "\n")
			}
			out[idx] = r
		}(s, lo, hi)
	}
	wg.Wait()
	var b strings.Builder
	first := true
	for _, o := range out {
		if o == "" {
			continue
		}
		if !first {
			b.WriteByte('\n')
		}
		b.WriteString(o)
		first = false
	}
	return b.String()
}

func TestProfileParallelRedaction(t *testing.T) {
	content := string(buildCodexTranscript(20 << 20))
	fmt.Printf("\ncores=%d  input=%dMB\n", runtime.NumCPU(), len(content)>>20)

	t0 := time.Now()
	seq, err := redact.JSONLContent(content)
	if err != nil {
		t.Fatal(err)
	}
	dSeq := time.Since(t0)
	fmt.Printf("%-24s %8s\n", "sequential", dSeq.Round(time.Millisecond))

	for _, sh := range []int{4, 8, 12} {
		t1 := time.Now()
		par := parallelJSONL(content, sh)
		d := time.Since(t1)
		identical := par == seq
		fmt.Printf("%-24s %8s   speedup=%.1fx  byte-identical=%v\n",
			fmt.Sprintf("parallel shards=%d", sh), d.Round(time.Millisecond),
			float64(dSeq)/float64(d), identical)
		if !identical {
			a, b := []byte(seq), []byte(par)
			fmt.Printf("   len seq=%d par=%d\n", len(a), len(b))
			for i := range a {
				if i >= len(b) || a[i] != b[i] {
					fmt.Printf("   first diff at %d: %q vs %q\n", i,
						string(a[max(0,i-40):min(len(a),i+40)]),
						string(b[max(0,i-40):min(len(b),i+40)]))
					break
				}
			}
		}
	}
	_ = bytes.Equal
}
EOF
