	}
	return b.String()
}

// padTo grows content past redactCacheMinBytes so the incremental path engages.
func padTo(t *testing.T, content string, minBytes int) string {
	t.Helper()
	var b strings.Builder
	b.WriteString(content)
	i := 0
	for b.Len() < minBytes {
		b.WriteString(transcriptLines(1_000_000+i, 200))
		i += 200
	}
	return b.String()
}

