	want := RedactBlobBytes(context.Background(), []byte(content), "full.jsonl", false)
	require.Equal(t, string(want), string(got))
	require.Nil(t, cache.load("full.jsonl"),
		"a single-JSON-value transcript must leave no cache entry to splice onto later")

	// Growing it (as OpenCode does, by inserting messages before the closing
	// braces) must still redact whole every time.
	grown := openCodeExport(t, redactCacheMinBytes+64*1024)
	got = writeAndRedact(t, repo, cache, dir, "full.jsonl", grown)
	want = RedactBlobBytes(context.Background(), []byte(grown), "full.jsonl", false)
	require.Equal(t, string(want), string(got))
	require.Nil(t, cache.load("full.jsonl"))
}
