		_ = json.Unmarshal(slowRaw, &entry.Slow) //nolint:errcheck // best-effort
	}

	// Extract time
	if tRaw, ok := raw["time"]; ok {
		var ts string
		if err := json.Unmarshal(tRaw, &ts); err == nil {
