import re, io
p = 'cmd/entire/cli/trace.go'
s = open(p).read()

# 1. Push the slow filter into collection so it composes with --last like --hook does.
old_doc = '''// collectTraceEntries reads a JSONL log file and returns the last N trace entries,
// ordered newest first. If hookFilter is non-empty, only entries with a matching
// Op field are included.
func collectTraceEntries(logFile string, last int, hookFilter string) ([]traceEntry, error) {'''
new_doc = '''// collectTraceEntries reads a JSONL log file and returns the last N trace entries,
// ordered newest first. If hookFilter is non-empty, only entries with a matching
// Op field are included; if slowOnly is set, only entries flagged slow are.
//
// Both filters are applied before the last-N truncation, so "the last N" always
// means the last N entries the caller asked to see. Filtering after truncation
// instead would make --slow return the slow entries among the last N traces
// rather than the last N slow traces — which reads as "no traces" whenever
// DEBUG logging fills the window with fast ones.
func collectTraceEntries(logFile string, last int, hookFilter string, slowOnly bool) ([]traceEntry, error) {'''
assert old_doc in s
s = s.replace(old_doc, new_doc)

old_filter = '''\t\tif hookFilter != "" && entry.Op != hookFilter {
\t\t\tcontinue
\t\t}'''
new_filter = '''\t\tif hookFilter != "" && entry.Op != hookFilter {
\t\t\tcontinue
\t\t}
\t\tif slowOnly && !entry.Slow {
\t\t\tcontinue
\t\t}'''
assert old_filter in s
s = s.replace(old_filter, new_filter)

# 2. percentileMs: implement the nearest-rank the doc comment promises.
old_pct = '''// percentileMs returns the p-th percentile of a sorted slice using nearest-rank,
// so p50 of one sample is that sample rather than an interpolation.
func percentileMs(sorted []int64, p int) int64 {
\tif len(sorted) == 0 {
\t\treturn 0
\t}
\tidx := (p * len(sorted)) / 100
\tif idx >= len(sorted) {
\t\tidx = len(sorted) - 1
\t}
\treturn sorted[idx]
}'''
new_pct = '''// percentileMs returns the p-th percentile of a sorted slice using nearest-rank,
// so p50 of one sample is that sample rather than an interpolation.
//
// The rank is ceil(p/100 * n), converted to a 0-based index. Truncating instead
// of rounding up overshoots by one whole sample whenever p*n divides evenly,
// which is exactly the round-numbered case: p90 of 10 samples would report the
// maximum, making the P90 and MAX columns duplicates of each other.
func percentileMs(sorted []int64, p int) int64 {
\tif len(sorted) == 0 {
\t\treturn 0
\t}
\tn := len(sorted)
\trank := (p*n + 99) / 100 // ceil(p*n/100)
\tidx := max(rank-1, 0)
\tif idx >= n {
\t\tidx = n - 1
\t}
\treturn sorted[idx]
}'''
assert old_pct in s
s = s.replace(old_pct, new_pct)

# 3. Do not emit a fabricated zero timestamp in --json.
old_time = '''\tSlow  bool        `json:"slow,omitempty"`
\tTime  time.Time   `json:"time"`'''
new_time = '''\tSlow bool `json:"slow,omitempty"`
\t// Time is omitted when zero rather than serialized as year 1: the parser
\t// tolerates a missing or malformed time key, and a JSON consumer should see
\t// the absence rather than a timestamp that was never recorded.
\tTime  time.Time   `json:"time,omitzero"`'''
assert old_time in s
s = s.replace(old_time, new_time)

open(p,'w').write(s)
print("trace.go patched")
PY

